  if(m.type==='board-interrupted'){title='登记中断，保留未知结果';description='先在DSH或原服务中核对任务已停止。此操作仅解除重复运行阻断，记录为中断待核对，不会制造成功或推进竞赛验收。';body=`<label class="ares-option"><input type="checkbox" data-modal-check="confirmStopped" ${m.confirmStopped?'checked':''}>我已实际核对原任务停止</label>`;footer=button('board-interrupted-save','登记中断','','primary');}
